import { z } from "zod";

import { kindFitsDirection } from "@/lib/categorise/engine";
import { isoDateIST } from "@/lib/dates";
import { parseRupeesToPaise } from "@/lib/money";

// Earliest date we accept for a manual entry.
export const MIN_TXN_DATE = "2000-01-01";

const emptyToNull = (v: string) => (v === "" ? null : v);

const ManualTransactionForm = z.object({
  // Generated by the form when it renders. Becomes the idempotency
  // fingerprint, so a double-submit or a retry saves the entry once.
  requestId: z.uuid(),
  accountId: z.uuid(),
  direction: z.enum(["DEBIT", "CREDIT"]),
  amount: z.string().max(30),
  txnDate: z.iso.date(),
  description: z.string().trim().min(1, "Add a short description").max(120),
  categoryId: z.union([z.uuid(), z.literal("")]).transform(emptyToNull),
  notes: z.string().trim().max(500).optional().default("").transform(emptyToNull),
});

export type ManualTransactionInput = {
  requestId: string;
  accountId: string;
  direction: "DEBIT" | "CREDIT";
  amountPaise: bigint;
  txnDate: string; // YYYY-MM-DD (IST calendar date)
  description: string;
  categoryId: string | null;
  notes: string | null;
};

export type FieldErrors = Partial<Record<keyof z.input<typeof ManualTransactionForm>, string>>;

export type ParsedInput =
  | { ok: true; data: ManualTransactionInput }
  | { ok: false; fieldErrors: FieldErrors };

/** Validates raw form fields. `now` is injectable for tests. */
export function parseManualTransaction(
  raw: Record<string, unknown>,
  now: Date = new Date(),
): ParsedInput {
  const parsed = ManualTransactionForm.safeParse(raw);
  if (!parsed.success) {
    const fieldErrors: FieldErrors = {};
    for (const issue of parsed.error.issues) {
      const key = issue.path[0] as keyof FieldErrors;
      fieldErrors[key] ??= issue.message;
    }
    return { ok: false, fieldErrors };
  }

  const { amount, ...rest } = parsed.data;
  const money = parseRupeesToPaise(amount);
  if (!money.ok) return { ok: false, fieldErrors: { amount: money.error } };

  // ISO dates compare correctly as strings.
  if (rest.txnDate > isoDateIST(now)) {
    return { ok: false, fieldErrors: { txnDate: "Date can't be in the future" } };
  }
  if (rest.txnDate < MIN_TXN_DATE) {
    return { ok: false, fieldErrors: { txnDate: "Date is too far in the past" } };
  }

  return { ok: true, data: { ...rest, amountPaise: money.paise } };
}

/** See kindFitsDirection: one rule shared by the server, rules engine and UI. */
export const categoryFitsDirection = kindFitsDirection;
